code='''def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    holes = []
    bar_rows = []
    for r in range(h):
        row_holes = []
        for c in range(1, w - 1):
            color = grid[r][c - 1]
            if color and grid[r][c] == 0 and grid[r][c + 1] == color:
                row_holes.append((r, c, color))
                out[r][c] = color
        if row_holes:
            holes.extend(row_holes)
            bar_rows.append(r)
    for r, c, color in holes:
        for rr in range(r - 1, -1, -1):
            if out[rr][c] != 0:
                break
            out[rr][c] = color
    if bar_rows:
        last_bar = max(bar_rows)
        for c in range(w):
            sources = [r for r in range(last_bar + 1, h) if grid[r][c] != 0]
            if not sources:
                continue
            top = min(sources)
            color = grid[top][c]
            for rr in range(top - 1, last_bar, -1):
                if out[rr][c] != 0:
                    break
                out[rr][c] = color
    return out
'''
